                                                   'Genauigkeit und Modellgröße:</p>\n'
                                                   '<table class="engine-table">\n'
                                                   '    <tr><th>Engine</th><th>Sprachen</th><th>Modellgröße</th><th>Am besten '
                                                   'für</th></tr>\n'
